package com.companages.controller;
import com.companages.dto.PositionDtos.*; import com.companages.service.PositionService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/organizations/{organizationId}/positions") public class PositionController { private final PositionService service; public PositionController(PositionService s){service=s;} @PostMapping ResponseEntity<Response> create(@PathVariable Long organizationId,@Valid @RequestBody Request r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(organizationId,r));} @GetMapping List<Response> list(@PathVariable Long organizationId){return service.list(organizationId);} @GetMapping("/{id}") Response get(@PathVariable Long organizationId,@PathVariable Long id){return service.get(organizationId,id);} @PutMapping("/{id}") Response update(@PathVariable Long organizationId,@PathVariable Long id,@Valid @RequestBody Request r){return service.update(organizationId,id,r);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable Long organizationId,@PathVariable Long id){service.delete(organizationId,id);} }
